// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());

        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.owner() != newOwner || (ok && c.owner() == newOwner && actor == c.owner()), "non-owner must not be able to change owner");
    }
}
